from typing import List

def find_kth(arr1: List[int], arr2: List[int], k: int) -> int:
    """
    Return the k-th smallest element (1-indexed) from the union of two sorted lists.
    """
    # Ensure arr1 is the shorter list for efficiency
    if len(arr1) > len(arr2):
        return find_kth(arr2, arr1, k)

    # Handle base cases
    if not arr1:
        return arr2[k - 1]
    if k == 1:
        return min(arr1[0], arr2[0])

    # Determine how many elements to discard from each array
    i = min(len(arr1), k // 2)
    j = min(len(arr2), k // 2)

    if arr1[i - 1] < arr2[j - 1]:
        # Discard first i elements of arr1 and adjust k
        return find_kth(arr1[i:], arr2, k - i)
    else:
        # Discard first j elements of arr2 and adjust k
        return find_kth(arr1, arr2[j:], k - j)

# Example usage
