def largest_subset(nums: List[int]) -> int:
    """
    Return the size of the largest subset of `nums` such that for every pair (a, b)
    in the subset, either a divides b or b divides a.
    """
    if not nums:
        return 0

    # Sort numbers to ensure divisibility checks only need to look back
    nums = sorted(nums)
    n = len(nums)
    dp = [1] * n  # dp[i] = size of largest divisible subset ending at nums[i]

    for i in range(n):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

