def is_samepatterns(pattern1, pattern2):
    """
    Return True if the two patterns follow the same sequence of repetitions,
    i.e. if there exists a bijection between the elements of pattern1 and
    pattern2 that preserves the order of appearance.

    Example:
        ["red", "green", "green"]  and ["a", "b", "b"] -> True
        ["red", "green", "blue"]   and ["a", "b", "b"] -> False
    """
    if len(pattern1) != len(pattern2):
        return False

    map1 = {}  # mapping from pattern1 element to pattern2 element
    map2 = {}  # mapping from pattern2 element to pattern1 element

    for a, b in zip(pattern1, pattern2):
        if a in map1:
            if map1[a] != b:
                return False
        else:
            map1[a] = b

        if b in map2:
            if map2[b] != a:
                return False
        else:
            map2[b] = a

    return True


# Example test
if __name__ == "__main__":
    assert is_samepatterns(["red", "green", "green"], ["a", "b", "b"]) == True
    print("All tests passed.")
