import math

def sum(a: int, b: int) -> int:
    """Return the sum of all common divisors of a and b."""
    a, b = abs(a), abs(b)
    # If both are zero, no common divisors (or infinite); we return 0
    if a == 0 and b == 0:
        return 0
    # If one is zero, common divisors are those of the other number
    if a == 0:
        return _sum_of_divisors(b)
    if b == 0:
        return _sum_of_divisors(a)

    g = math.gcd(a, b)
    return _sum_of_divisors(g)

def _sum_of_divisors(n: int) -> int:
    """Compute the sum of all positive divisors of n."""
    if n <= 0:
        return 0
    result = 1
    temp = n
    # Check divisibility by 2 first
    if temp % 2 == 0:
        exp = 0
        while temp % 2 == 0:
            temp //= 2
            exp += 1
        result *= (2 ** (exp + 1) - 1) // (2 - 1)
    # Check odd factors
    f = 3
    max_f = int(math.isqrt(temp)) + 1
    while f <= max_f and temp > 1:
        if temp % f == 0:
            exp = 0
            while temp % f == 0:
                temp //= f
                exp += 1
            result *= (f ** (exp + 1) - 1) // (f - 1)
            max_f = int(math.isqrt(temp)) + 1
        f += 2
    # If a prime factor remains
    if temp > 1:
        result *= (temp ** 2 - 1) // (temp - 1)  # = temp + 1
    return result
