import math

def _comb(n: int, k: int) -> int:
    """Compute C(n, k) without using math.comb (for older Python versions)."""
    if k < 0 or k > n:
        return 0
    k = min(k, n - k)
    result = 1
    for i in range(1, k + 1):
        result = result * (n - k + i) // i
    return result

def count_binary_seq(n: int) -> float:
    """
    Count binary sequences of length 2n such that the sum of the first n bits
    equals the sum of the last n bits.

    The count is the central binomial coefficient C(2n, n).
    The function returns a float to satisfy the test using math.isclose.
    """
    try:
        # Python 3.8+ has math.comb
        return float(math.comb(2 * n, n))
    except AttributeError:
        return float(_comb(2 * n, n))

# Example test
if __name__ == "__main__":
    assert math.isclose(count_binary_seq(1), 2.0, rel_tol=0.001)
    print("All tests passed.")
