def find_kth(arr1: List[Any], arr2: List[Any], k: int) -> Any:
    """
    Return the k-th smallest element (1-indexed) from the union of two sorted lists.
    The input lists may contain any comparable elements (numbers, strings, bools, etc.).
    """
    # Sort the input arrays to guarantee order
    a1 = sorted(arr1)
    a2 = sorted(arr2)

    def kth(a: List[Any], b: List[Any], k: int) -> Any:
        # If one array is empty, return the k-th element from the other
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]

        # Base case: k == 1
        if k == 1:
            return a[0] if a[0] < b[0] else b[0]

        # Determine how many elements to compare from each array
        i = min(len(a), k // 2)
        j = min(len(b), k // 2)

        # Recursively discard the smaller half
        if a[i - 1] < b[j - 1]:
            return kth(a[i:], b, k - i)
        else:
