import math

def sum(a: int, b: int) -> int:
    """Return the sum of all common divisors of a and b."""
    a, b = abs(a), abs(b)

    # Handle zero cases
    if a == 0 and b == 0:
        return 0
    if a == 0 or b == 0:
        # Common divisors of 0 and n are the divisors of |n|
        return _sum_divisors(a or b)

    g = math.gcd(a, b)
    return _sum_divisors(g)

def _sum_divisors(n: int) -> int:
    """Return the sum of all positive divisors of n."""
    if n == 0:
        return 0
    total = 0
    limit = int(math.isqrt(n))
    for i in range(1, limit + 1):
        if n % i == 0:
            total += i
            j = n // i
            if j != i:
                total += j
    return total
