from typing import List

def max_sum(arr: List[int]) -> int:
    """
    Return the maximum sum of a bitonic subsequence in `arr`.
    A bitonic subsequence first strictly increases then strictly decreases.
    """
    n = len(arr)
    if n == 0:
        return 0

    # dp_inc[i] = maximum sum of an increasing subsequence ending at i
    dp_inc = [0] * n
    # dp_dec[i] = maximum sum of a decreasing subsequence starting at i
    dp_dec = [0] * n

    # Compute increasing subsequence sums
    for i in range(n):
        dp_inc[i] = arr[i]  # at least the element itself
        for j in range(i):
            if arr[j] < arr[i]:
                dp_inc[i] = max(dp_inc[i], dp_inc[j] + arr[i])

    # Compute decreasing subsequence sums
    for i in reversed(range(n)):
        dp_dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dp_dec[i] = max(dp_dec[i], dp_dec[j] + arr[i])

    # Find maximum bitonic sum (peak at i)
    max_bitonic = 0
    for i in range(n):
        # A valid bitonic subsequence requires at least one element on both sides
        # of the peak. We enforce that by checking dp_inc and dp_dec contain
        # more than just the peak element.
        inc_len = 1
        dec_len = 1
        # Count elements in increasing part
        for j in range(i):
            if arr[j] < arr[i] and dp_inc[j] + arr[i] == dp_inc[i]:
                inc_len += 1
        # Count elements in decreasing part
        for j in range(i + 1, n):
            if arr[j] < arr[i] and dp_dec[j] + arr[i] == dp_dec[i]:
                dec_len += 1

        if inc_len > 1 and dec_len > 1:
            max_bitonic = max(max_bitonic, dp_inc[i] + dp_dec[i] - arr[i])

    # If no proper bitonic subsequence exists, fall back to the maximum element
    return max_bitonic if max_bitonic > 0 else max(arr, default=0)

# Example usage:
if __name__ == "__main__":
    assert max_sum([1, 15, 51, 45, 33, 100, 12, 18, 9]) == 194
    assert max_sum([80, 60, 30, 40, 20, 10]) == 210
    assert max_sum([2, 3, 14, 16, 21, 23, 29, 30]) == 41
    print("All tests passed.")
