from typing import List, Any

def find_kth(arr1: List[Any], arr2: List[Any], k: int) -> Any:
    """
    Return the k-th smallest element (1‑indexed) from the union of two lists.
    The input lists may be unsorted; they are sorted internally before searching.
    """
    if k <= 0:
        raise ValueError("k must be a positive integer")

    # Work on sorted copies to avoid mutating the original lists
    a = sorted(arr1)
    b = sorted(arr2)

    # Recursive helper that operates on the sorted lists
    def _kth(a: List[Any], b: List[Any], k: int) -> Any:
        # Ensure a is the shorter list
        if len(a) > len(b):
            return _kth(b, a, k)

        # If a is empty, the answer is in b
        if not a:
            return b[k - 1]

        # If we only need the smallest element
        if k == 1:
            return a[0] if a[0] < b[0] else b[0]

        # Determine how many elements to discard from each list
        i = min(len(a), k // 2)
        j = min(len(b), k // 2)

        # Compare the i-th and j-th elements and discard the smaller side
        if a[i - 1] < b[j - 1]:
            return _kth(a[i:], b, k - i)
        else:
            return _kth(a, b[j:], k - j)

    # The total number of elements must be at least k
    total_len = len(a) + len(b)
    if k > total_len:
        raise ValueError(f"k={k} is larger than the total number of elements ({total_len})")

    return _kth(a, b, k)

# Example usage and tests
